<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\DiscordChannel; use App\Models\DiscordGuild; use App\Models\VoiceAudioClip; use App\Models\VoiceRecording; use App\Models\VoiceReport; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class VoiceAudioClipController extends Controller { public function store(Request $request): JsonResponse { $data=$request->validate(['voice_report_id'=>'required|uuid|exists:voice_reports,id','guild_discord_id'=>'required|string|max:255','channel_discord_id'=>'required|string|max:255','reported_user_discord_id'=>'required|string|max:255','storage_path'=>'required|string|max:2000','mime_type'=>'required|string|max:255','size_bytes'=>'required|integer|min:0','duration_seconds'=>'required|integer|min:0|max:3600','captured_from'=>'required|date','captured_until'=>'required|date']); $report=VoiceReport::query()->findOrFail($data['voice_report_id']); $guild=DiscordGuild::query()->where('discord_id',$data['guild_discord_id'])->firstOrFail(); $channel=DiscordChannel::query()->voiceBased()->where('discord_id',$data['channel_discord_id'])->firstOrFail(); $recording=VoiceRecording::query()->firstOrCreate(['voice_report_id'=>$report->id],['discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'status'=>'captured','captured_from'=>$data['captured_from'],'captured_until'=>$data['captured_until']]); $clip=VoiceAudioClip::query()->create(['voice_recording_id'=>$recording->id,'voice_report_id'=>$report->id,'discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>$data['reported_user_discord_id'],'storage_path'=>$data['storage_path'],'mime_type'=>$data['mime_type'],'size_bytes'=>$data['size_bytes'],'duration_seconds'=>$data['duration_seconds'],'captured_from'=>$data['captured_from'],'captured_until'=>$data['captured_until'],'status'=>'captured']); $recording->refreshSummary(); return response()->json(['data'=>['id'=>$clip->id,'recording_id'=>$recording->id]],201); } }
